      activeIndex,
      isTextHovered,
      pieContainer,
      barContainer,
      lineContainer,
      stackedContainer,
      handleTextHover,
      resetHover,
      handleTextClick,
      formatSimpleText,
      hasData,
      isValidPieData,
      pieData,
      simpleBarData,
      lineData,
      formatNumber,
      processedField
